    (1, 1, 'acorn', 12, '2026-10-02'), (2, 1, 'hazelnut', 5, '2026-10-09'),
    (3, 2, 'acorn', 3, '2026-10-05'), (4, 3, 'beechnut', 20, '2026-09-28'),
    (5, 3, 'acorn', 7, '2026-10-11'), (6, 4, 'hazelnut', 2, '2026-10-12'),
